using MiniPharmacie.Business.Security;
using MiniPharmacie.Data.Database;
using Microsoft.Data.Sqlite;

namespace MiniPharmacie.Business.Services;

public sealed class SecurityAdministrationService(DatabaseInitializer db)
{
    public async Task<bool> HasAnyUserAsync(CancellationToken ct=default){await using var c=db.CreateConnection();await c.OpenAsync(ct);await using var q=c.CreateCommand();q.CommandText="SELECT EXISTS(SELECT 1 FROM Users)";return Convert.ToInt64(await q.ExecuteScalarAsync(ct))!=0;}
    public async Task<long> CreateInitialAdministratorAsync(string username,string password,CancellationToken ct=default){Validate(username,password);await using var c=db.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);await using var q=c.CreateCommand();q.Transaction=(Microsoft.Data.Sqlite.SqliteTransaction)tx;q.CommandText="SELECT COUNT(*) FROM Users";if(Convert.ToInt64(await q.ExecuteScalarAsync(ct))!=0)throw new InvalidOperationException("Le compte initial a déjà été créé.");q.CommandText="INSERT OR IGNORE INTO Roles(Name) VALUES('Responsable'),('Vendeur');INSERT INTO Users(RoleId,Username,PasswordHash,CreatedAt) SELECT Id,$u,$h,$d FROM Roles WHERE Name='Responsable';SELECT last_insert_rowid()";q.Parameters.AddWithValue("$u",username.Trim());q.Parameters.AddWithValue("$h",PasswordHasher.Hash(password));q.Parameters.AddWithValue("$d",DateTimeOffset.Now.ToString("O"));var id=Convert.ToInt64(await q.ExecuteScalarAsync(ct));q.Parameters.Clear();q.CommandText="INSERT INTO AuditLog(UserId,Action,Entity,EntityId,OccurredAt,Details) VALUES($u,'PREMIER_RESPONSABLE_CREE','Users',$u,$d,$name)";q.Parameters.AddWithValue("$u",id);q.Parameters.AddWithValue("$d",DateTimeOffset.Now.ToString("O"));q.Parameters.AddWithValue("$name",username.Trim());await q.ExecuteNonQueryAsync(ct);await tx.CommitAsync(ct);return id;}
    public async Task<long> CreateUserAsync(long actorId,string username,string password,string role,CancellationToken ct=default){Validate(username,password);if(role is not("Responsable" or "Vendeur"))throw new ArgumentException("Rôle inconnu.");await using var c=db.CreateConnection();await c.OpenAsync(ct);await RequireManager(c,actorId,ct);await using var q=c.CreateCommand();q.CommandText="INSERT INTO Users(RoleId,Username,PasswordHash,CreatedAt) SELECT Id,$u,$h,$d FROM Roles WHERE Name=$role;SELECT last_insert_rowid()";q.Parameters.AddWithValue("$u",username.Trim());q.Parameters.AddWithValue("$h",PasswordHasher.Hash(password));q.Parameters.AddWithValue("$d",DateTimeOffset.Now.ToString("O"));q.Parameters.AddWithValue("$role",role);var id=Convert.ToInt64(await q.ExecuteScalarAsync(ct));await Audit(c,actorId,"UTILISATEUR_CREE","Users",id,username.Trim(),ct);return id;}
    public async Task<IReadOnlyList<(long Id,string Username,string Role,bool Active)>> ListUsersAsync(long actorId,CancellationToken ct=default){await using var c=db.CreateConnection();await c.OpenAsync(ct);await RequireManager(c,actorId,ct);await using var q=c.CreateCommand();q.CommandText="SELECT u.Id,u.Username,r.Name,u.IsActive FROM Users u JOIN Roles r ON r.Id=u.RoleId ORDER BY u.Username";var rows=new List<(long,string,string,bool)>();await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))rows.Add((r.GetInt64(0),r.GetString(1),r.GetString(2),r.GetInt32(3)==1));return rows;}
    public async Task DeactivateUserAsync(long actorId,long targetId,CancellationToken ct=default){await using var c=db.CreateConnection();await c.OpenAsync(ct);await RequireManager(c,actorId,ct);if(actorId==targetId)throw new InvalidOperationException("Vous ne pouvez pas désactiver votre propre compte.");await using var q=c.CreateCommand();q.CommandText="UPDATE Users SET IsActive=0 WHERE Id=$id AND IsActive=1;INSERT INTO AuditLog(UserId,Action,Entity,EntityId,OccurredAt,Details) VALUES($actor,'UTILISATEUR_DESACTIVE','Users',$id,$d,'')";q.Parameters.AddWithValue("$id",targetId);q.Parameters.AddWithValue("$actor",actorId);q.Parameters.AddWithValue("$d",DateTimeOffset.Now.ToString("O"));if(await q.ExecuteNonQueryAsync(ct)<1)throw new InvalidOperationException("Utilisateur introuvable ou déjà désactivé.");}
    public static async Task RequireManager(SqliteConnection c,long actorId,CancellationToken ct=default){await using var q=c.CreateCommand();q.CommandText="SELECT r.Name FROM Users u JOIN Roles r ON r.Id=u.RoleId WHERE u.Id=$id AND u.IsActive=1";q.Parameters.AddWithValue("$id",actorId);if(!string.Equals((string?)await q.ExecuteScalarAsync(ct),"Responsable",StringComparison.OrdinalIgnoreCase))throw new UnauthorizedAccessException("Opération réservée au responsable.");}
    private static async Task Audit(SqliteConnection c,long actor,string action,string entity,long id,string details,CancellationToken ct){await using var q=c.CreateCommand();q.CommandText="INSERT INTO AuditLog(UserId,Action,Entity,EntityId,OccurredAt,Details) VALUES($u,$a,$e,$i,$d,$x)";q.Parameters.AddWithValue("$u",actor);q.Parameters.AddWithValue("$a",action);q.Parameters.AddWithValue("$e",entity);q.Parameters.AddWithValue("$i",id);q.Parameters.AddWithValue("$d",DateTimeOffset.Now.ToString("O"));q.Parameters.AddWithValue("$x",details);await q.ExecuteNonQueryAsync(ct);}
    private static void Validate(string username,string password){if(string.IsNullOrWhiteSpace(username)||username.Length<3)throw new ArgumentException("L'identifiant doit comporter au moins 3 caractères.");if(string.IsNullOrWhiteSpace(password)||password.Length<12)throw new ArgumentException("Le mot de passe doit comporter au moins 12 caractères.");}
}
